<template>
  <section class="transcript-inbox">
    <template v-if="!selected">
      <header class="page-header">
        <div><p class="eyebrow">Zoom imports</p><h1>Transcript Inbox</h1><p>Review incoming source material, then decide what needs to happen next. Nothing is analysed automatically.</p></div>
        <span v-if="errorMessage" class="type-metadata text-state-danger" role="status">Inbox unavailable</span>
      </header>

      <div v-if="transcripts.length" class="queue-controls">
        <label class="inbox-search"><span class="sr-only">Search transcripts</span><input v-model="searchQuery" class="control-field min-h-touch" type="search" placeholder="Search transcripts" /></label>
        <div class="filters" role="group" aria-label="Transcript views">
          <button v-for="filter in filters" :key="filter.id" type="button" class="min-h-touch type-ui" :class="{ active: filterMode === filter.id }" :aria-pressed="filterMode === filter.id" @click="setFilter(filter.id)">{{ filter.label }}<template v-if="filter.id === 'attention'"> · {{ actionableCount }}</template></button>
        </div>
      </div>

      <p v-if="errorMessage" class="notice error" role="alert">{{ errorMessage }}</p>
      <div v-if="loading" class="empty-card compact">Loading transcripts…</div>
      <div v-else-if="!errorMessage && !transcripts.length" class="empty-card compact"><h2>Inbox up to date</h2><p>New Zoom transcripts will appear here when they need review.</p></div>
      <div v-else-if="visibleTranscripts.length" class="inbox-list">
        <button v-for="transcript in visibleTranscripts" :key="transcript.id" class="transcript-row" @click="openTranscript(transcript)">
          <span class="row-main">
            <strong>{{ rowTitle(transcript) }}</strong>
            <small>{{ formatDate(transcript.receivedAt) }}<template v-if="transcript.meetingId"> · Meeting {{ transcript.meetingId }}</template></small>
            <p v-if="!transcript.clientId" class="transcript-preview">{{ transcriptPreview(transcript) }}</p>
          </span>
          <StatusIndicator v-if="filterMode === 'attention'" :tone="workflowTone(transcript)">{{ workflowState(transcript).label }}</StatusIndicator>
          <span class="open">{{ filterMode === 'history' ? 'View' : primaryAction(transcript) }} <span aria-hidden="true">›</span></span>
        </button>
        <div v-if="hasMoreHistory" class="load-more-row"><button class="load-more" type="button" @click="historyLimit += historyPageSize">Load more</button></div>
      </div>
      <div v-else class="empty-card compact"><h2>{{ filterMode === 'attention' && !searchQuery ? 'Inbox up to date' : 'No matching transcripts' }}</h2><p>{{ filterMode === 'attention' && !searchQuery ? 'New Zoom transcripts will appear here when they need review.' : 'Try another search term or view.' }}</p></div>
    </template>

    <template v-else>
      <header class="review-header">
        <div class="header-main">
          <button class="back" @click="selected = null">‹ Transcript Inbox</button>
          <div class="title-area">
            <p class="eyebrow">Transcript review</p>
            <h1>{{ labelFor(selected) }}</h1>
            <p>{{ formatDate(selected.receivedAt) }} · original Zoom transcript</p>
          </div>
        </div>
        <div class="header-actions">
          <button v-if="isEligibleForDeletion" class="secondary text-state-danger" :disabled="saving" @click="deleteTranscript">Delete transcript</button>
        </div>
      </header>
      <p v-if="errorMessage" class="notice error" role="alert">{{ errorMessage }}</p><p v-else-if="successMessage" class="notice success" role="status">{{ successMessage }}</p>
      <ol class="review-progress" aria-label="Transcript review progress"><li :class="{ complete: selected.clientId, current: !selected.clientId }"><span>{{ selected.clientId ? '✓' : '1' }}</span><div><strong>Client</strong><small>{{ selected.clientId ? clientName(selected.clientId) : 'Choose client' }}</small></div></li><li :class="{ complete: selected.sessionRef, current: selected.clientId && !selected.sessionRef }"><span>{{ selected.sessionRef ? '✓' : '2' }}</span><div><strong>Session</strong><small>{{ selected.sessionRef ? 'Linked' : 'Link or create a session' }}</small></div></li><li :class="{ complete: selected.reviewChoicesSavedAt, current: selected.sessionRef && !selected.reviewChoicesSavedAt }"><span>{{ selected.reviewChoicesSavedAt ? '✓' : '3' }}</span><div><strong>Review choices</strong><small>{{ selected.reviewChoicesSavedAt ? 'Saved' : 'Choose output and retention' }}</small></div></li></ol>
      <section class="workflow-section client-section"><template v-if="!selected.clientId || editingClient"><div><p class="eyebrow">Client</p><h2>Client</h2><p>Select the client this original Zoom transcript belongs to. Helio will not guess.</p></div><div class="assignment-controls"><label for="client-select">Client</label><select id="client-select" v-model="selectedClientId"><option value="" disabled>Select a client…</option><option v-for="client in clients" :key="client.id" :value="client.id">{{ client.name }}</option></select><p v-if="!clients.length" class="field-help">Add a client first, then return here to assign this transcript.</p><div class="assignment-actions"><button v-if="selected.clientId" class="secondary" :disabled="saving" @click="editingClient = false">Cancel</button><button class="primary" :disabled="saving || !selectedClientId || selectedClientId === selected.clientId" @click="saveAssignment">{{ saving ? 'Saving…' : selected.clientId ? 'Change client' : 'Assign client' }}</button></div></div></template><template v-else><div><p class="eyebrow">Client</p><h2>{{ clientName(selected.clientId) }}</h2><p>Assigned client</p></div><button class="secondary" @click="editingClient = true">Change</button></template></section>
      <section v-if="selected.clientId" class="workflow-section session-section"><template v-if="!selected.sessionRef || editingSession"><div><p class="eyebrow">Session</p><h2>Session</h2><p>Link this transcript to an existing session or create a new one.</p></div><div class="assignment-controls"><label for="session-select">Session</label><select id="session-select" v-model="selectedSessionRef"><option value="" disabled>Select a session…</option><option v-for="session in sessionsForClient" :key="session.id" :value="String(session.id)">{{ sessionOptionLabel(session) }}</option></select><p v-if="!sessionsForClient.length" class="field-help">No sessions for this client yet. Create one from this transcript when you are ready.</p><div class="assignment-actions"><button class="secondary" :disabled="saving" @click="createSessionFromTranscript">{{ saving ? 'Creating…' : 'Create session' }}</button><button v-if="selected.sessionRef" class="secondary" :disabled="saving" @click="editingSession = false">Cancel</button><button class="primary" :disabled="saving || !selectedSessionRef || selectedSessionRef === selected.sessionRef" @click="saveSessionLink">{{ saving ? 'Saving…' : selected.sessionRef ? 'Change session' : 'Link session' }}</button></div></div></template><template v-else><div><p class="eyebrow">Session</p><h2>Linked session</h2><p>This transcript is linked to one therapeutic encounter.</p></div><button class="secondary" @click="editingSession = true">Change</button></template></section>
      <section class="raw-transcript"><header><div><h2>Original transcript</h2><p>This is the original transcript imported from Zoom. Helio has not analysed or changed it.</p></div><div class="source-actions"><button class="secondary" :aria-expanded="showRaw" @click="showRaw = !showRaw">{{ showRaw ? 'Hide original transcript' : 'View original transcript' }}</button><button class="secondary download" @click="downloadRaw(selected)">Download .txt</button></div></header><pre v-if="showRaw">{{ selected.text }}</pre></section>
      <section v-if="selected.clientId && selected.sessionRef && (!selected.reviewChoicesSavedAt || editingChoices)" class="review-choices"><div><p class="eyebrow">Review choices</p><h2>Review choices</h2><p>Choose what, if anything, should be requested later and how the original source should be retained. This does not start analysis.</p></div><label for="clinical-output">Requested output</label><select id="clinical-output" v-model="selectedLens"><option value="">No output requested</option><option value="clinical_summary">Clinical summary</option><option value="draft_note">Draft clinical note</option><option value="cbt">CBT reflection</option></select><fieldset><legend>Source retention</legend><label><input v-model="sourceRetention" type="radio" value="keep_until_review" /> Keep the original source until I review it</label><label><input v-model="sourceRetention" type="radio" value="delete_after_approved_output" /> Mark for deletion after I approve an output</label></fieldset><div class="assignment-actions"><button v-if="selected.reviewChoicesSavedAt" class="secondary" :disabled="saving" @click="editingChoices = false">Cancel</button><button class="primary save-choices" :disabled="saving" @click="saveReviewChoices">{{ saving ? 'Saving…' : selected.reviewChoicesSavedAt ? 'Update review choices' : 'Save review choices' }}</button></div></section>
      <section v-if="selected.reviewChoicesSavedAt && !editingChoices && !selected.completedAt" class="ready-card"><div><p class="eyebrow">Review choices</p><h2>Review choices saved</h2><p>The transcript has been triaged. Any requested output is only a preference for later work; nothing has been generated. Continue clinical work in the linked session.</p></div><div class="assignment-actions"><button class="secondary" @click="editingChoices = true">Change choices</button><button class="primary" :disabled="saving" @click="openLinkedSession">Open session</button></div></section><section v-if="selected.completedAt" class="ready-card complete-card"><div><p class="eyebrow">Triage complete</p><h2>Transcript triage complete</h2><p>Client, session and review choices have been recorded. No requested output or Clinical Record was created by this triage step.</p></div><button class="secondary" @click="openLinkedSession">View session</button></section>
    </template>
  </section>
</template>
<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { authenticatedFetch } from '../lib/api.js'
import { createSessionFromTranscript as createTranscriptSession, listSessions } from '../lib/sessions.js'
import StatusIndicator from './ui/StatusIndicator.vue'
const props = defineProps({ clients: { type: Array, default: () => [] }, openTranscriptId: { type: [String, Number], default: null } })
const router = useRouter()
const transcripts = ref([]), selected = ref(null), selectedClientId = ref(''), selectedSessionRef = ref(''), selectedLens = ref(''), sourceRetention = ref('keep_until_review')
const editingClient = ref(false), editingSession = ref(false), editingChoices = ref(false), searchQuery = ref(''), filterMode = ref('attention'), showRaw = ref(false)
const loading = ref(true), saving = ref(false), errorMessage = ref(''), successMessage = ref(''), sessionRecords = ref([])
const historyPageSize = 20
const historyLimit = ref(historyPageSize)
const isEligibleForDeletion = computed(() => {
  if (!selected.value) return false;
  return selected.value.status === 'unassigned' &&
    !selected.value.clientId &&
    !selected.value.sessionRef &&
    !selected.value.reviewChoicesSavedAt &&
    !selected.value.completedAt;
});
const filters = [{ id: 'attention', label: 'Needs attention' }, { id: 'history', label: 'History' }]
const actionableCount = computed(() => transcripts.value.filter(item => workflowState(item).id !== 'complete').length)
const sessionsForClient = computed(() => sessionRecords.value.filter(session => String(session.clientId) === String(selected.value?.clientId)).sort((a,b)=>new Date(b.startedAt||b.createdAt||0)-new Date(a.startedAt||a.createdAt||0)))
const matchingTranscripts = computed(() => { const query = searchQuery.value.trim().toLowerCase(); return transcripts.value.filter(item => { const state = workflowState(item); if (filterMode.value === 'attention' && state.id === 'complete') return false; if (filterMode.value === 'history' && state.id !== 'complete') return false; if (!query) return true; return labelFor(item).toLowerCase().includes(query) || rowTitle(item).toLowerCase().includes(query) || clientName(item.clientId).toLowerCase().includes(query) || state.label.toLowerCase().includes(query) || formatDate(item.receivedAt).toLowerCase().includes(query) }).sort((a,b)=>new Date(b.receivedAt||0)-new Date(a.receivedAt||0)) })
const visibleTranscripts = computed(() => filterMode.value === 'history' ? matchingTranscripts.value.slice(0, historyLimit.value) : matchingTranscripts.value)
const hasMoreHistory = computed(() => filterMode.value === 'history' && visibleTranscripts.value.length < matchingTranscripts.value.length)
function setFilter(id){ filterMode.value=id; historyLimit.value=historyPageSize }
function formatDate(value){ return new Date(value).toLocaleString(undefined,{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}) }
function labelFor(transcript){ return transcript.meetingId ? `Zoom meeting ${transcript.meetingId}` : 'Zoom transcript' }
function rowTitle(transcript){ return clientName(transcript.clientId) || labelFor(transcript) }
function transcriptPreview(transcript){
  if (!transcript.text) return '';
  const preview = transcript.text.replace(/\s+/g, ' ').trim().slice(0, 100);
  return preview.length >= 100 ? `${preview}…` : preview;
}
function workflowState(transcript){ if(!transcript?.clientId||transcript.status==='unassigned')return{id:'needs-client',label:'Needs client'};if(!transcript.sessionRef)return{id:'needs-session',label:'Needs session'};if(!transcript.reviewChoicesSavedAt)return{id:'needs-review',label:'Needs review'};if(transcript.completedAt)return{id:'complete',label:'Triage complete'};return{id:'review-saved',label:'Review choices saved'} }
function workflowTone(transcript){ return ({'needs-client':'warning','needs-session':'neutral','needs-review':'warning','review-saved':'success','complete':'success'})[workflowState(transcript).id] || 'neutral' }
function primaryAction(transcript){ return ({'needs-client':'Assign client','needs-session':'Link session','needs-review':'Review transcript','review-saved':'Open session',complete:'View'})[workflowState(transcript).id] }
function clientName(clientId){ return props.clients.find(client=>client.id===clientId)?.name||'' }
function sessionOptionLabel(session){ const state=({planned:'Planned',in_progress:'In progress',completed:'Completed',closed:'Closed'})[session.status]||'Completed';return `${formatDate(session.startedAt||session.createdAt)} · ${state}` }
async function loadSessionRecords(){ try{sessionRecords.value=await listSessions()}catch(error){errorMessage.value=error?.message||'Unable to load sessions.';sessionRecords.value=[]} }
function replaceTranscript(transcript){const index=transcripts.value.findIndex(item=>item.id===transcript.id);if(index>=0)transcripts.value[index]=transcript;selected.value=transcript}
function openTranscript(transcript){
  selected.value=transcript;
  selectedClientId.value=transcript.clientId||'';
  const linkedSession=sessionRecords.value.find(session=>String(session.id)===String(transcript.sessionRef)||String(session.legacyRef||'')===String(transcript.sessionRef));
  selectedSessionRef.value=linkedSession?.id||transcript.sessionRef||'';
  selectedLens.value=transcript.requestedLens||'';
  sourceRetention.value=transcript.sourceRetention||'keep_until_review';
  errorMessage.value='';
  successMessage.value='';
  showRaw.value=false;
  loadSessionRecords();
  window.scrollTo({ top: 0, behavior: 'smooth' });
}
async function load(){loading.value=true;errorMessage.value='';try{const response=await authenticatedFetch('/api/zoom/transcripts');const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Unable to load transcripts.');transcripts.value=data.transcripts||[]}catch(error){errorMessage.value=error.message||'Unable to load transcripts.'}finally{loading.value=false}}
async function patchTranscript(body,fallbackMessage){saving.value=true;errorMessage.value='';successMessage.value='';try{const response=await authenticatedFetch('/api/zoom/transcripts',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:selected.value.id,expectedUpdatedAt:selected.value.updatedAt,...body})});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||fallbackMessage);replaceTranscript(data.transcript);return data.transcript}catch(error){errorMessage.value=error.message||fallbackMessage;return null}finally{saving.value=false}}
async function saveAssignment(){const transcript=await patchTranscript({clientId:selectedClientId.value},'Unable to save the client assignment.');if(transcript){selectedSessionRef.value='';editingClient.value=false;successMessage.value=`Assigned to ${clientName(transcript.clientId)}. Link the session next.`}}
async function saveSessionLink(){const transcript=await patchTranscript({sessionRef:selectedSessionRef.value},'Unable to link this session.');if(transcript){editingSession.value=false;successMessage.value='Session linked. Review transcript handling next.'}}
async function createSessionFromTranscript(){if(!selected.value?.clientId)return;saving.value=true;errorMessage.value='';try{const newSession=await createTranscriptSession(selected.value.clientId,selected.value.receivedAt);sessionRecords.value=[newSession,...sessionRecords.value.filter(session=>session.id!==newSession.id)];selectedSessionRef.value=String(newSession.id);await saveSessionLink()}catch(error){errorMessage.value=error?.message||'Unable to create a session from this transcript.'}finally{saving.value=false}}
async function saveReviewChoices(){const transcript=await patchTranscript({requestedLens:selectedLens.value||null,sourceRetention:sourceRetention.value,reviewChoicesSaved:true},'Unable to save review choices.');if(transcript){editingChoices.value=false;successMessage.value='Review choices saved. No analysis has started.'}}
async function deleteTranscript(){if(!selected.value)return;if(!window.confirm('Delete this unassigned transcript? This permanently removes the imported source from Helios.'))return;saving.value=true;errorMessage.value='';successMessage.value='';try{const response=await authenticatedFetch('/api/zoom/transcripts',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:selected.value.id})});if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error(data.error||'Unable to delete transcript.')}transcripts.value=transcripts.value.filter(item=>item.id!==selected.value.id);selected.value=null;successMessage.value='Transcript deleted.'}catch(error){errorMessage.value=error.message||'Unable to delete transcript.'}finally{saving.value=false}}
async function openLinkedSession(){if(!selected.value?.sessionRef)return;if(selected.value.reviewChoicesSavedAt&&!selected.value.completedAt){const completed=await patchTranscript({markComplete:true},'Unable to complete transcript triage.');if(!completed)return}await router.push({name:'SessionWorkspace',params:{clientId:selected.value.clientId,sessionId:selected.value.sessionRef}})}
function downloadRaw(transcript){const blob=new Blob([transcript.text],{type:'text/plain;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`helio-zoom-transcript-${transcript.meetingId||transcript.id}.txt`;link.click();URL.revokeObjectURL(link.href)}
async function openQueuedTranscript(id){if(!id)return;if(!transcripts.value.length)await load();const transcript=transcripts.value.find(item=>String(item.id)===String(id));if(transcript)openTranscript(transcript)}
watch(()=>props.openTranscriptId,openQueuedTranscript);watch(searchQuery,()=>{historyLimit.value=historyPageSize});onMounted(async()=>{await Promise.all([load(),loadSessionRecords()]);openQueuedTranscript(props.openTranscriptId)})
</script>
<style scoped>
.transcript-inbox{max-width:68rem;margin:0 auto;color:var(--text-primary)}.page-header{display:flex;align-items:flex-start;justify-content:space-between;gap:var(--space-inline-lg);margin-bottom:var(--space-stack-xl)}.eyebrow{margin:0 0 var(--space-stack-xs);color:var(--text-muted);font:600 var(--type-eyebrow-size)/var(--type-eyebrow-line) var(--font-ui);letter-spacing:var(--type-eyebrow-tracking);text-transform:uppercase}.page-header h1,.review-header h1{margin:0;font:600 var(--type-page-title-size)/var(--type-page-title-line) var(--font-ui);letter-spacing:var(--type-page-title-tracking)}.page-header p:not(.eyebrow),.review-header p:not(.eyebrow){margin:var(--space-stack-xs) 0 0;color:var(--text-muted);font:400 var(--type-body-size)/var(--type-body-line) var(--font-ui)}.queue-controls{display:flex;align-items:center;justify-content:space-between;gap:var(--space-inline-lg);margin:0 0 var(--space-stack-lg);padding-bottom:var(--space-stack-lg);border-bottom:1px solid var(--border-muted)}.inbox-search{display:block;flex:0 1 24rem}.filters{display:flex;gap:var(--space-inline-xs);padding:var(--space-inline-xs);background:var(--surface-muted);border:1px solid var(--border-muted);border-radius:var(--radius-control)}.filters button{border:0;background:transparent;border-radius:var(--radius-control);padding:0 var(--space-inline-md);color:var(--text-muted)}.filters button.active{background:var(--surface-elevated);color:var(--text-primary);font-weight:600}.notice{margin:0 0 var(--space-stack-lg);padding:var(--space-stack-md);border-radius:var(--radius-control)}.notice.error{background:var(--state-danger-surface);color:var(--state-danger)}.notice.success{background:var(--state-success-surface);color:var(--state-success)}.empty-card{min-height:18rem;display:flex;flex-direction:column;justify-content:center;align-items:center;border:1px solid var(--border-muted);border-radius:var(--radius-panel);padding:var(--space-stack-2xl);text-align:center;color:var(--text-muted)}.empty-card.compact{min-height:9rem;background:transparent;border-style:dashed}.empty-card h2{color:var(--text-secondary);margin:var(--space-stack-xs);font:600 var(--type-section-title-size)/var(--type-section-title-line) var(--font-editorial)}.empty-card p{max-width:30rem;line-height:var(--type-body-line);margin:var(--space-stack-xs)}.inbox-list{border-top:1px solid var(--border-muted);border-bottom:1px solid var(--border-muted)}.transcript-row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;align-items:center;gap:var(--space-inline-lg);width:100%;border:0;border-bottom:1px solid var(--border-muted);background:transparent;padding:var(--space-stack-md) var(--space-inline-xs);text-align:left;color:var(--text-secondary)}.transcript-row:last-of-type{border-bottom:0}.transcript-row:hover{background:var(--surface-subtle)}.row-main{display:flex;min-width:0;flex-direction:column;gap:var(--space-stack-xs)}.row-main strong{font:600 var(--type-body-size)/var(--type-body-line) var(--font-ui);color:var(--text-primary)}.row-main small{color:var(--text-muted);font:500 var(--type-metadata-size)/var(--type-metadata-line) var(--font-ui)}.open{color:var(--action-link);font:600 var(--type-ui-size)/var(--type-ui-line) var(--font-ui);white-space:nowrap}.load-more-row{text-align:center;padding:var(--space-stack-md) 0;border-top:1px solid var(--border-muted)}.load-more,.back{border:0;background:transparent;color:var(--action-link);font:600 var(--type-ui-size)/var(--type-ui-line) var(--font-ui);padding:var(--space-stack-sm) var(--space-inline-md)}.review-header{margin-bottom:var(--space-stack-lg)}.review-progress{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--space-inline-sm);list-style:none;padding:0;margin:0 0 var(--space-stack-lg)}.review-progress li{display:flex;gap:var(--space-inline-sm);align-items:center;padding:var(--space-stack-sm) var(--space-inline-md);border:1px solid var(--border-muted);border-radius:var(--radius-control);background:var(--surface-elevated);color:var(--text-muted)}.review-progress li>span{display:grid;place-items:center;width:1.45rem;height:1.45rem;border-radius:var(--radius-pill);background:var(--border-muted);color:var(--text-secondary);font:700 var(--type-metadata-size)/1 var(--font-ui)}.review-progress strong,.review-progress small{display:block}.review-progress small{font-size:var(--type-metadata-size);margin-top:var(--space-stack-xs)}.review-progress .complete{border-color:var(--state-success);background:var(--state-success-surface);color:var(--state-success)}.review-progress .complete>span{background:var(--state-success);color:var(--text-on-action)}.review-progress .current{background:var(--state-selected);color:var(--action-link-hover)}.review-progress .current>span{background:var(--action-link);color:var(--text-on-action)}.workflow-section,.raw-transcript,.review-choices,.ready-card{background:var(--surface-elevated);border:1px solid var(--border-muted);border-radius:var(--radius-panel);padding:var(--space-stack-lg);margin-bottom:var(--space-stack-lg)}.workflow-section{display:grid;grid-template-columns:minmax(0,1fr) minmax(18rem,24rem);gap:var(--space-stack-xl);align-items:center;background:var(--surface-muted)}.workflow-section>button{justify-self:end}.workflow-section h2,.raw-transcript h2,.ready-card h2,.review-choices h2{font:600 var(--type-subsection-size)/var(--type-subsection-line) var(--font-ui);margin:var(--space-stack-xs) 0}.workflow-section p:not(.eyebrow),.raw-transcript p,.ready-card p,.review-choices p:not(.eyebrow){color:var(--text-muted);font:400 var(--type-body-size)/var(--type-body-line) var(--font-ui);margin:var(--space-stack-xs) 0}.assignment-controls select,.review-choices select{width:100%;box-sizing:border-box;border:1px solid var(--border);border-radius:var(--radius-control);min-height:var(--control-target);padding:0 var(--space-inline-md);font:400 var(--type-body-size)/var(--type-body-line) var(--font-ui);color:var(--text-secondary);background:var(--surface-elevated)}